using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed partial class UnitDirectiveCancelHoldingTests
{
 static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
 static NewMilitaryInput Input(WorldSession s,NewMilitaryAction action)=>new(new("request:unit-recipient/"+s.Revision+"/"+action),action);
 static void Send(WorldSession s,NewMilitaryAction action,long amount=0){var result=s.DecideNewMilitary(Input(s,action) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);}
 static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
 static WorldSession Away(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{ObservationPolicy=NewGameMilitary.ObservationContract},s.PlayerControl,s.Revision).Code);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+90000,a.Y-10000),B=new(a.X+90000,a.Y+10000)},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Max(l=>l.EndAt)+1);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Max(l=>l.EndAt)+1);return s;}
 static NewMilitaryInput Query(WorldSession s,int unit)=>Input(s,NewMilitaryAction.InquireUnitKnown) with{InquiryTarget=new(NewGameMilitary.UnitRecipientContract,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[unit])!),PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};
 static TroopDispatch Dispatch(WorldSession s,int unit){var i=Query(s,unit);var r=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();}
 static UnitPostInquiryAnswer Answer(ContractWorld w,TroopReceipt receipt)=>ContractJson.Read<UnitPostInquiryAnswer>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==receipt.ReplyMessage).Body));

 static NewMilitaryInput Directive(WorldSession s,int unit,UnitDirectiveKind kind){var w=s.DiagnosticSnapshot();var k=NewGameMilitary.SelectKnownTarget(w,NewGameMilitary.UnitIds[unit])!;return Input(s,NewMilitaryAction.SendUnitDirective) with{Directive=new(NewGameMilitary.UnitDirectiveContract,k,kind,kind==UnitDirectiveKind.Move?new(k.Position.X+8000,k.Position.Y):null),DeliverBy=s.Seconds+600,PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract,OriginalPolicy=NewGameMilitary.UnitDirectiveHoldingContract};}

 static TroopDispatch FailedOriginal(WorldSession s,bool learn=true,int index=1,UnitDirectiveKind kind=UnitDirectiveKind.Move,bool holding=true){Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);var i=Directive(s,index,kind) with{OriginalPolicy=holding?NewGameMilitary.UnitDirectiveHoldingContract:null};Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var root=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();At(s,root.DueAt);var r=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Receipts.Last();Assert.False(r.Delivered);if(learn)At(s,r.ReplyDueAt);return root;}
 static void HomeUnits(WorldSession s){long end=s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max();At(s,Math.Max(s.Seconds,end+2));}
 static NewMilitaryInput Retry(WorldSession s,TroopDispatch root)=>Input(s,NewMilitaryAction.RetryUnitDirective) with{DirectiveRetry=new(NewGameMilitary.UnitDirectiveRetryContract,root.Id,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),root.Recipient)!),TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};

 static UnitHeldTransfer Handoff(WorldSession s,TroopDispatch root){var paper=NewGameMilitary.SelectDirectivePaper(s.DiagnosticSnapshot(),root.Id);Assert.NotNull(paper);var input=Input(s,NewMilitaryAction.DeliverHeldUnitDirective) with{DirectiveHandoff=paper};var result=s.DecideNewMilitary(input,s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();}
 static TroopDispatch Cancel(WorldSession s,TroopDispatch root,long? effective=null,bool retained=true){var w=s.DiagnosticSnapshot();var p=new UnitDirectiveCancellationInput(NewGameMilitary.UnitDirectiveCancellationContract,root.Id,NewGameMilitary.SelectKnownTarget(w,root.Recipient)!,effective??s.Seconds);var i=Input(s,NewMilitaryAction.CancelUnitDirective) with{OriginalPolicy=retained?NewGameMilitary.UnitDirectiveCancelHoldingContract:null,DirectiveCancellation=p,DeliverBy=s.Seconds+600,PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};var result=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Dispatches.Last();}
 static TroopDispatch MissedCancel(WorldSession s,bool learn=true){Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);var i=Directive(s,1,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var command=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();var d=Cancel(s,command);At(s,d.DueAt);var r=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single();Assert.False(r.Delivered);if(learn)At(s,r.ReplyDueAt);return d;}
 static NewMilitaryInput RetryCancel(WorldSession s,TroopDispatch root)=>Input(s,NewMilitaryAction.RetryUnitDirectiveCancellation) with{DirectiveCancelRetry=new(NewGameMilitary.UnitDirectiveCancelRetryContract,root.Id,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),root.Recipient)!),TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};

 static UnitHeldTransfer HandCancel(WorldSession s,TroopDispatch root){var p=NewGameMilitary.SelectDirectiveCancellationPaper(s.DiagnosticSnapshot(),root.Id);Assert.NotNull(p);var i=Input(s,NewMilitaryAction.DeliverHeldUnitDirectiveCancellation) with{DirectiveCancelHandoff=p};var r=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();}
 [Fact]public void RealRetainedCancellationArrivesLateOnceAndReturnsPhysicalAcknowledgment(){var s=Away();var root=MissedCancel(s);HomeUnits(s);var initial=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single();Assert.Contains(NewGameMilitary.HeldPapers(s.DiagnosticSnapshot(),s.Seconds),h=>h.Message==root.Message);var t=HandCancel(s,root);At(s,t.DueAt-1);var restored=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,restored})At(v,t.DueAt);var w=s.DiagnosticSnapshot();Assert.Single(w.NewMilitary!.UnitDirective!.Cancellation!.Effects);Assert.Equal(root.Id,w.NewMilitary.UnitDirective.Cancellation.Effects.Single().Id);Assert.False(NewGameMilitary.ReceiptConfirmedToSender(w,root.Message,w.PlayerControl.Value));Assert.Equal(ContractJson.CanonicalHash(initial),ContractJson.CanonicalHash(w.NewMilitary.UnitDirective.Cancellation.Receipts.Single()));var ack=w.NewMilitary.UnitDirective.Cancellation.Holding!.Outcomes.Single();Assert.True(ack.Received);foreach(var v in new[]{s,restored})At(v,ack.DueAt);w=s.DiagnosticSnapshot();Assert.True(NewGameMilitary.ReceiptConfirmedToSender(w,root.Message,w.PlayerControl.Value));Assert.Contains("未実行の対象原本を取消",NewGameMilitary.UnitDirectiveCancellationOriginalStatus(w,root.Id));Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));new WorldSession(w);}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)]
 public void InvalidCancellationPaperReferenceIsAtomic(int variant){var s=Away();var root=MissedCancel(s);HomeUnits(s);var p=NewGameMilitary.SelectDirectiveCancellationPaper(s.DiagnosticSnapshot(),root.Id)!;Assert.NotNull(p);var i=Input(s,NewMilitaryAction.DeliverHeldUnitDirectiveCancellation) with{DirectiveCancelHandoff=p};i=variant switch{0=>i with{DirectiveCancelHandoff=p with{Contract="wrong"}},1=>i with{DirectiveCancelHandoff=p with{Cancellation=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.First().Id}},2=>i with{DirectiveCancelHandoff=p with{Attempt="missing/1"}},3=>i with{DirectiveCancelHandoff=p with{Carrier=new("courier:missing")}},4=>i with{DirectiveCancelHandoff=p with{Known=p.Known with{Position=new(p.Known.Position.X+1,p.Known.Position.Y)}}},5=>i with{TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract},6=>i with{DeliverBy=s.Seconds+600},_=>i with{DirectiveCancelHandoff=null}};string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
 [Fact]public void InitialMissDoesNotInventLocalPaperBeforeCourierActuallyReturns(){var s=Away();var root=MissedCancel(s,false);Assert.DoesNotContain(NewGameMilitary.HeldPapers(s.DiagnosticSnapshot(),s.Seconds),h=>h.Message==root.Message);Assert.Null(NewGameMilitary.SelectDirectiveCancellationPaper(s.DiagnosticSnapshot(),root.Id));var r=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single();At(s,r.ReplyDueAt-1);Assert.DoesNotContain(NewGameMilitary.HeldPapers(s.DiagnosticSnapshot(),s.Seconds),h=>h.Message==root.Message);At(s,r.ReplyDueAt);Assert.Contains(NewGameMilitary.HeldPapers(s.DiagnosticSnapshot(),s.Seconds),h=>h.Message==root.Message&&h.Attempt==root.Attempt);new WorldSession(s.DiagnosticSnapshot());}
 [Fact]public void UndeclaredCancellationCannotAcquireARetroactiveOriginal(){var s=Away();Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);var i=Directive(s,1,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var d=Cancel(s,s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last(),retained:false);At(s,d.DueAt);At(s,s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single().ReplyDueAt);HomeUnits(s);var w=s.DiagnosticSnapshot();Assert.Null(w.NewMilitary!.UnitDirective!.Cancellation!.Holding);Assert.DoesNotContain(NewGameMilitary.HeldPapers(w,s.Seconds),h=>h.Message==d.Message);Assert.Null(NewGameMilitary.SelectDirectiveCancellationPaper(w,d.Id));Assert.DoesNotContain("HoldingPolicy",w.Messaging.Messages.Single(m=>m.Id==d.Message).Body);var bytes=ContractJson.Write(w.NewMilitary.UnitDirective.Cancellation);Assert.DoesNotContain("\"Holding\"",System.Text.Encoding.UTF8.GetString(bytes));new WorldSession(w);}
 [Fact]public void RetainedCancellationCannotExtendOriginalDeadline(){var s=Away();var d=MissedCancel(s);HomeUnits(s);long end=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==d.Message).DeliverBy!.Value;At(s,end+1);Assert.Null(NewGameMilitary.SelectDirectiveCancellationPaper(s.DiagnosticSnapshot(),d.Id));Assert.Contains(NewGameMilitary.HeldPapers(s.DiagnosticSnapshot(),s.Seconds),h=>h.Message==d.Message);Assert.Empty(s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Effects);}
 [Fact]public void CopyAndRealCancellationOriginalAtSameTickHaveOneCanonicalEffect(){var s=Away();var d=MissedCancel(s);HomeUnits(s);var t=HandCancel(s,d);var i=RetryCancel(s,d);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var copy=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Dispatches.Last();Assert.Equal(t.DueAt,copy.DueAt);At(s,t.DueAt-1);var other=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,other})At(v,t.DueAt);var w=s.DiagnosticSnapshot();Assert.Single(w.Messaging.Receipts,r=>r.MessageId==d.Message);Assert.Single(w.NewMilitary!.UnitDirective!.Cancellation!.Effects);Assert.Equal(d.Id,w.NewMilitary.UnitDirective.Cancellation.Effects.Single().Id);Assert.False(w.NewMilitary.UnitDirective.Cancellation.Receipts.First().Delivered);long end=Math.Max(w.NewMilitary.UnitDirective.Cancellation.Holding!.Outcomes.Single().DueAt,w.NewMilitary.UnitDirective.Cancellation.Receipts.Last().ReplyDueAt);foreach(var v in new[]{s,other})At(v,end);Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(other.DiagnosticSnapshot()));Assert.False(NewGameMilitary.UnitDirectiveCancelRetryAllowed(s.DiagnosticSnapshot(),d.Id));}
 [Fact]public void ForgedReturnedCancellationHolderIsRejectedOnRestore(){var s=Away();var d=MissedCancel(s);var w=s.DiagnosticSnapshot();var x=w.NewMilitary!.UnitDirective!.Cancellation!;var h=x.Holding!;int n=Array.FindIndex(h.Holdings,p=>p.Message==d.Message);Assert.True(n>=0);h.Holdings[n]=h.Holdings[n] with{Holder=new("courier:forged")};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
 [Fact]public void FutureCancellationLateReceiptReturnsWaitingThenPhysicalEffectNotice(){var s=Away();Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);var i=Directive(s,1,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var d=Cancel(s,s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last(),s.Seconds+180);At(s,d.DueAt);At(s,s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single().ReplyDueAt);HomeUnits(s);var t=HandCancel(s,d);At(s,t.DueAt);var ack=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Holding!.Outcomes.Single();Assert.Empty(s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Effects);At(s,ack.DueAt);Assert.Contains("効力時刻を待つ",NewGameMilitary.UnitDirectiveCancellationOriginalStatus(s.DiagnosticSnapshot(),d.Id));long effective=ContractJson.Read<UnitDirectiveCancellationNote>(System.Text.Encoding.UTF8.GetBytes(s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==d.Message).Body)).EffectiveAt;At(s,effective-1);var other=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,other})At(v,effective);var notice=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Notices.Single();Assert.Equal(t.Origin,notice.Destination);Assert.Contains("効力時刻を待つ",NewGameMilitary.UnitDirectiveCancellationOriginalStatus(s.DiagnosticSnapshot(),d.Id));foreach(var v in new[]{s,other})At(v,notice.DueAt);Assert.Contains("未実行の対象原本を取消",NewGameMilitary.UnitDirectiveCancellationOriginalStatus(s.DiagnosticSnapshot(),d.Id));Assert.Equal(ContractJson.CanonicalHash(s.DiagnosticSnapshot()),ContractJson.CanonicalHash(other.DiagnosticSnapshot()));}
 static void PersonOffCamp(WorldSession s){var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(a.X-20000,a.Y)},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max()+1);}
 [Fact]public void LostCancellationLateAckIsRecoveredOnlyByActualPaper(){var s=Away();PersonOffCamp(s);var root=MissedCancel(s);HomeUnits(s);var t=HandCancel(s,root);At(s,t.DueAt);var f=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Holding!.Outcomes.Single();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(a.X-40000,a.Y)},s.PlayerControl,s.Revision).Code);At(s,f.DueAt);var w=s.DiagnosticSnapshot();Assert.False(MessageFlow.Knows(w.Messaging,f.ReplyMessage!,w.PlayerControl.Value));Assert.Contains(NewGameMilitary.HeldPapers(w,s.Seconds),h=>h.Message==f.ReplyMessage&&h.Holder==t.Carrier);long end=w.NewMilitary!.Withdrawal!.Journeys.Last().Route.Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max();At(s,Math.Max(s.Seconds,end+1));Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=f.Destination},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max()+1);Assert.True(NewGameMilitary.HeldAllowed(s.DiagnosticSnapshot(),NewMilitaryAction.TakeHeldReply));Send(s,NewMilitaryAction.TakeHeldReply);var take=s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();Assert.Equal(f.ReplyMessage,take.Message);var restored=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,restored})At(v,take.DueAt);w=s.DiagnosticSnapshot();Assert.True(MessageFlow.Knows(w.Messaging,f.ReplyMessage!,w.PlayerControl.Value));Assert.Contains("未実行の対象原本を取消",NewGameMilitary.UnitDirectiveCancellationOriginalStatus(w,root.Id));Assert.True(NewGameMilitary.ReceiptConfirmedToSender(w,root.Message,w.PlayerControl.Value));Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));new WorldSession(w);}
 [Fact]public void CancellationOriginalAndUndeliveredFailureReportMoveWithSameActualCarrier(){var s=Away();PersonOffCamp(s);var d=MissedCancel(s,false);var receipt=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single();var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=new(a.X-40000,a.Y)},s.PlayerControl,s.Revision).Code);At(s,receipt.ReplyDueAt);Assert.False(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,receipt.ReplyMessage,s.PlayerControl.Value));At(s,Math.Max(s.Seconds,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max()+1));HomeUnits(s);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=receipt.ReplyDestination},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max()+1);var t=HandCancel(s,d);Assert.Contains(d.Attempt,t.Cargo);Assert.Contains(receipt.ReplyAttempt,t.Cargo);At(s,t.DueAt-1);var papers=NewGameMilitary.HeldPapers(s.DiagnosticSnapshot(),s.Seconds);Assert.Equal(papers.Single(h=>h.Attempt==d.Attempt).Position,papers.Single(h=>h.Attempt==receipt.ReplyAttempt).Position);At(s,t.DueAt);var f=CancellationPaperAck(s);At(s,Math.Min(f.DueAt-1,s.Seconds+1));var w=s.DiagnosticSnapshot();var frame=NewGameMilitary.CourierFrames(w,w.ElapsedSeconds).Single(c=>c.Carrier==t.Carrier);var report=NewGameMilitary.HeldPapers(w,s.Seconds).Single(h=>h.Attempt==receipt.ReplyAttempt);Assert.Equal(frame.Position,report.Position);new WorldSession(w);}
 static UnitDirectiveCancelLateReceipt CancellationPaperAck(WorldSession s)=>s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Holding!.Outcomes.Single();
 [Fact]public void CancellationPaperCannotBeRedirectedToDifferentUnit(){var s=Away();var d=MissedCancel(s);HomeUnits(s);var p=NewGameMilitary.SelectDirectiveCancellationPaper(s.DiagnosticSnapshot(),d.Id)!;Assert.NotNull(p);var known=NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[2])!;Assert.NotNull(known);var input=Input(s,NewMilitaryAction.DeliverHeldUnitDirectiveCancellation) with{DirectiveCancelHandoff=p with{Known=known}};string before=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
}
